test_buttons.c
#include <pthread.h>
#include <stdint.h>
#include <unity.h>

#include "runner/button_latch.h"

#define POLL_MS 5

static ButtonLatch latch;

/* Samples the button every POLL_MS from `from` up to (not including) `to`. */
static void hold(bool down, uint32_t from, uint32_t to) {
  for (uint32_t t = from; (uint32_t)(to - t) != 0 && (uint32_t)(to - t) < 0x80000000u;
       t += POLL_MS)
    button_latch_sample(&latch, down, t);
}

void setUp(void) {
  button_latch_init(&latch, 30);
  button_latch_sample(&latch, false, 0);
}
void tearDown(void) {}

void test_a_button_left_alone_gives_nothing_to_take(void) {
  hold(false, 5, 1000);
  TEST_ASSERT_FALSE(button_latch_take(&latch, NULL));
}

void test_a_click_is_one_press_taken_once(void) {
  hold(false, 5, 100);
  hold(true, 100, 250);
  hold(false, 250, 400);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
  TEST_ASSERT_TRUE(button_latch_take(&latch, NULL));
  TEST_ASSERT_FALSE(button_latch_take(&latch, NULL));
}

void test_a_press_only_counts_once_it_has_settled(void) {
  hold(true, 100, 125);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
  hold(true, 125, 135);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
}

void test_a_long_press_is_still_one_press(void) {
  hold(true, 100, 5000);
  TEST_ASSERT_EQUAL_UINT32(1, button_latch_pending(&latch));
}

void test_a_glitch_shorter_than_the_settle_time_is_ignored(void) {
  hold(true, 100, 120);
  hold(false, 120, 400);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
}

void test_an_old_glitch_does_not_shorten_the_settle_time_of_a_later_press(void) {
  hold(true, 100, 120);
  hold(false, 120, 400);
  hold(true, 400, 425);
  TEST_ASSERT_EQUAL_UINT32(0, button_latch_pending(&latch));
#ifndef RUNNER_BUTTON_LATCH_H
#define RUNNER_BUTTON_LATCH_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Remembers button presses that arrive while the main loop is busy, so a hack
 * with a long draw step cannot make a press vanish. A background task feeds it
 * samples of the button line every few milliseconds; the main loop takes the
 * presses. The line only counts as changed once it has held its new level for
 * the settle time, so bounce on press or release cannot produce extra presses. */
typedef struct {
  volatile uint32_t lock; /* guards pending and first_ms, which change together */
  volatile uint32_t pending;
  volatile uint32_t first_ms;
  uint32_t settle_ms;
  uint32_t candidate_since_ms;
  bool has_sample;
  bool stable_down;
  bool candidate_down;
} ButtonLatch;

void button_latch_init(ButtonLatch *l, uint32_t settle_ms);

/* One reading of the line (down is true while the button is pressed) taken at
 * now_ms. The first sample only sets the starting state, so a button held at
 * boot is not a press. */
void button_latch_sample(ButtonLatch *l, bool down, uint32_t now_ms);

/* Presses confirmed and not yet taken. */
uint32_t button_latch_pending(const ButtonLatch *l);

/* True if any press is pending. All pending presses are consumed at once, since
 * extra presses during a long step are almost always retries. When began_ms is
 * not NULL it receives the time the earliest press taken began. */
bool button_latch_take(ButtonLatch *l, uint32_t *began_ms);

#ifdef __cplusplus
}
#endif

#endif

