HackRunner *runner_create_with(Canvas *canvas, const HackEntry *const *hacks,
                               int count);
void runner_destroy(HackRunner *r);

/* Stops any running hack, clears the canvas, loads defaults, runs init.
 * Returns 0, or -1 for a bad index. */
